export function calculateColumnHeightFromElements(
  column: Element,
  mailOptions: MailOptions,
  webVersion?: boolean,
  threeColumns = false
): number {
  const columnWidth = threeColumns ? 192 : 294;
  const contentWidth = columnWidth - 40;

  const imageWidth = contentWidth - 24;

  const tempContainer = document.createElement('div');

  tempContainer.style.cssText = `
    position:absolute;
    left:-9999px;
    top:-9999px;
    width:${contentWidth}px;
    visibility:hidden;
    pointer-events:none;
    font-family:Roboto,sans-serif;
    font-size:16px;
    line-height:24px;
    color:#512b2b;
  `;

  document.body.appendChild(tempContainer);

  try {
    let elementHtml = '';

    column.subElements?.forEach((subElement, index) => {
      let subElementHtml = getElementHtml(mailOptions, subElement, true, webVersion);

      subElementHtml = subElementHtml
        .replaceAll('"600"', `"${contentWidth}"`)
        .replaceAll('"560"', `"${contentWidth}"`)
        .replaceAll('width="600"', `width="${contentWidth}"`)
        .replaceAll('width="560"', `width="${contentWidth}"`)
        .replaceAll('max-width:600px;', `max-width:${contentWidth}px;`)
        .replaceAll('max-width:560px;', `max-width:${contentWidth}px;`)
        .replaceAll('width:600px;', `width:${contentWidth}px;`)
        .replaceAll('width:560px;', `width:${contentWidth}px;`)
        .replaceAll('576', `${imageWidth}`);

      elementHtml += subElementHtml;

      if (column.subElements && index < column.subElements.length - 1) {
        elementHtml += getSpacing(column.subElements, index);
      }
    });

    tempContainer.innerHTML = `
      <table
        cellpadding="0"
        cellspacing="0"
        border="0"
        width="${contentWidth}"
        style="width:${contentWidth}px;font-family:Roboto,sans-serif;font-size:16px;color:#512b2b;"
      >
        <tr>
          <td
            width="${contentWidth}"
            style="width:${contentWidth}px;font-family:Roboto,sans-serif;font-size:16px;color:#512B2B;line-height:24px;background-color:${column.options.color.toLowerCase()};"
          >
            ${elementHtml}
          </td>
        </tr>
      </table>
    `;

    // content height + top/bottom padding from the exported column body
    return Math.ceil(tempContainer.getBoundingClientRect().height + 40);
  } finally {
    document.body.removeChild(tempContainer);
  }
}

function removeVariables(html: string) {
  return html.replace(/,?\s\B\$\w+/, "");
}

/**
 * Filters out all content, whether element or text, between an #if and an #end Conditional in a list of Elements.
 * Checks elements, nested elements and text inside elements.
 *
 * @param elements - list of Element type objects to be filtered
 * @returns List of Elements where the content between Conditionals have been filtered out.
 */
function filterConditionalContent(elements: Element[]): Element[] {
  const filteredElements: Element[] = [];
  let conditionalActive = false;

  elements.forEach((element) => {
    const isStartConditional = element.type === Element_Type.CONDITIONAL && element.options.text.startsWith("#if");
    const isEndConditional = element.type === Element_Type.CONDITIONAL && element.options.text.startsWith("#end");

    if (isStartConditional) {
      conditionalActive = true;
    } else if (isEndConditional) {
      conditionalActive = false;
    } else if (!conditionalActive) {
      filteredElements.push(filterConditionalContentInElement(element));
    }
  })

  return filteredElements;
}

/**
 * Filters out all content between an #if and an #end Conditional in a single Element.
 * Checks nested elements and text inside elements.
 *
 * @param element - Element type object to be filtered
 * @returns Element with filtered conditional content.
 */
function filterConditionalContentInElement(element: Element): Element {
  if (element.subElements && element.subElements.length > 0) {
    return {...element,
      subElements: filterConditionalContent(element.subElements)};
  } else if (element.options.text?.toString().includes("#")) {
    return {...element,
      options: {...element.options,
        text: element.options.text.replaceAll(/#if.+?#end/g, "")}};
  }
  return element;
}

function generateImageUrl(element: Element, mailOptions: MailOptions, preview: boolean) {
  if (preview) return getImageUrl(element);
  else if (element.options.imageUrl) return element.options.imageUrl
  else if (element.options.fileName) return 'https://www.swedbank.' + mailOptions.country.toLowerCase() + '/proinfo-files/' + element.options.fileName;
}

export function returnMCR(mailOptions: MailOptions) {
  return mailOptions.new_MCR ? '$MCR' : mailOptions.MCR.toString()
}